"""Bounded LibreOffice SVG conversion and multi-slide SVG splitting."""

import copy
import os
import shutil
import subprocess
from pathlib import Path
from typing import Protocol

from lxml import etree

_MAX_SVG_CHARACTERS = 16_000_000
_MAX_SVG_ELEMENTS = 250_000
_MAX_SLIDES = 1_000
_METADATA_CLASSES = frozenset(
    {"Background", "BackgroundObjects", "DateTime", "Footer", "PageNumber", "Header"}
)


class LibreOfficeConversionError(RuntimeError):
    """A machine-identifiable conversion or emitted-SVG failure."""

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        super().__init__(f"{code}: {message}")


class SvgConverter(Protocol):
    """Injectable port for converting one supported source document to SVG."""

    def convert(self, source: Path, output_dir: Path) -> Path:
        """Convert source and return the path of the produced SVG document."""
        ...


class LibreOfficeSvgConverter:
    """Invoke a specific LibreOffice binary without involving a shell."""

    def __init__(self, soffice: Path, timeout_seconds: float = 60.0) -> None:
        if timeout_seconds <= 0:
            raise LibreOfficeConversionError("invalid_conversion_timeout", "timeout must be positive")
        self._soffice = soffice
        self._timeout_seconds = timeout_seconds

    def convert(self, source: Path, output_dir: Path) -> Path:
        output_dir.mkdir(parents=True, exist_ok=True)
        expected = output_dir / f"{source.stem}.svg"
        try:
            result = subprocess.run(
                [
                    str(self._soffice),
                    "--headless",
                    "--norestore",
                    "--convert-to",
                    "svg",
                    "--outdir",
                    str(output_dir),
                    str(source),
                ],
                check=False,
                capture_output=True,
                text=True,
                timeout=self._timeout_seconds,
            )
        except subprocess.TimeoutExpired as error:
            raise LibreOfficeConversionError(
                "libreoffice_timeout", f"conversion exceeded {self._timeout_seconds:g} seconds"
            ) from error
        except OSError as error:
            raise LibreOfficeConversionError(
                "libreoffice_unavailable", f"could not execute LibreOffice: {error}"
            ) from error
        if result.returncode != 0:
            detail = (result.stderr or result.stdout).strip()[:500] or "no diagnostic output"
            raise LibreOfficeConversionError(
                "libreoffice_conversion_failed",
                f"LibreOffice exited with {result.returncode}: {detail}",
            )
        if not expected.is_file():
            raise LibreOfficeConversionError(
                "libreoffice_output_missing", f"LibreOffice did not create {expected.name}"
            )
        return expected


def discover_soffice() -> Path | None:
    """Locate LibreOffice using configuration, PATH, then standard Windows locations."""
    configured = os.environ.get("SOFFICE_PATH")
    candidates: list[Path] = []
    if configured:
        candidates.append(Path(configured))
    on_path = shutil.which("soffice")
    if on_path:
        candidates.append(Path(on_path))
    candidates.extend(
        (
            Path(os.environ.get("ProgramFiles", r"C:\Program Files"))
            / "LibreOffice"
            / "program"
            / "soffice.exe",
            Path(os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)"))
            / "LibreOffice"
            / "program"
            / "soffice.exe",
        )
    )
    return next((candidate for candidate in candidates if candidate.is_file()), None)


def converter_version(soffice: Path) -> str:
    """Return LibreOffice's display version, or ``unknown`` when it cannot be queried."""
    try:
        result = subprocess.run(
            [str(soffice), "--version"],
            check=False,
            capture_output=True,
            text=True,
            timeout=10,
        )
    except (OSError, subprocess.TimeoutExpired):
        return "unknown"
    if result.returncode != 0:
        return "unknown"
    first_line = result.stdout.strip().splitlines()
    return first_line[0].strip()[:64] if first_line and first_line[0].strip() else "unknown"


def split_slides(svg_text: str) -> tuple[str, ...]:
    """Split LibreOffice's multi-page SVG into standalone, non-metadata-only slides."""
    if len(svg_text) > _MAX_SVG_CHARACTERS:
        raise LibreOfficeConversionError("svg_too_large", "SVG exceeds the 16,000,000 character limit")
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False, huge_tree=False)
    try:
        root = etree.fromstring(svg_text.encode("utf-8"), parser)
    except (etree.XMLSyntaxError, ValueError) as error:
        raise LibreOfficeConversionError("invalid_svg", f"SVG is not well-formed: {error}") from error
    elements = tuple(root.iter())
    if len(elements) > _MAX_SVG_ELEMENTS:
        raise LibreOfficeConversionError("svg_too_complex", "SVG element count exceeds limit")
    slide_nodes = tuple(node for node in elements if _has_class(node, "Slide"))
    if len(slide_nodes) > _MAX_SLIDES:
        raise LibreOfficeConversionError("too_many_slides", "SVG slide count exceeds limit")
    definitions = tuple(child for child in root if _local_name(child) == "defs")
    documents: list[str] = []
    for slide in slide_nodes:
        pages = tuple(node for node in slide.iter() if _has_class(node, "Page"))
        if not any(_page_has_drawing(page) for page in pages):
            continue
        standalone = etree.Element(root.tag, attrib=dict(root.attrib), nsmap=root.nsmap)
        standalone.text = root.text
        for definition in definitions:
            standalone.append(copy.deepcopy(definition))
        standalone.append(copy.deepcopy(slide))
        documents.append(etree.tostring(standalone, encoding="unicode"))
    return tuple(documents)


def _has_class(element: etree._Element, class_name: str) -> bool:
    return class_name in element.get("class", "").split()


def _local_name(element: etree._Element) -> str:
    tag = element.tag
    return etree.QName(tag).localname if isinstance(tag, str) else ""


def _page_has_drawing(page: etree._Element) -> bool:
    return any(
        _local_name(child) != "g"
        or not set(child.get("class", "").split()).intersection(_METADATA_CLASSES)
        for child in page
    )

"""Externalize SVG image data and inventory embedded and theme fonts."""

import base64
import binascii
import hashlib
import re
from pathlib import Path, PurePosixPath
from typing import Mapping
from zipfile import BadZipFile, ZipFile, ZipInfo

from lxml import etree

from impromptu_ingestion.render.contracts import EmbeddedFont, RenderAsset

_ALLOWED_MEDIA_TYPES = {
    "image/png": "png",
    "image/jpeg": "jpg",
    "image/gif": "gif",
    "image/svg+xml": "svg",
}
_DATA_URI = re.compile(r"^data:([^;,]+);base64,(.*)$", re.DOTALL)
_MAX_SVG_CHARACTERS = 16_000_000
_MAX_ASSETS = 2_000
_MAX_ASSET_BYTES = 16_000_000
_MAX_TOTAL_ASSET_BYTES = 128_000_000
_MAX_ZIP_PARTS = 10_000
_MAX_FONT_PARTS = 128
_MAX_FONT_BYTES = 8_000_000
_MAX_XML_BYTES = 2_000_000
_A_NS = "http://schemas.openxmlformats.org/drawingml/2006/main"
_P_NS = "http://schemas.openxmlformats.org/presentationml/2006/main"
_R_NS = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
_REL_NS = "http://schemas.openxmlformats.org/package/2006/relationships"


class AssetExternalizationError(RuntimeError):
    """A machine-identifiable unsafe or malformed SVG asset failure."""

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        super().__init__(f"{code}: {message}")


class FontExtractionError(RuntimeError):
    """A machine-identifiable unsafe or malformed PPTX font failure."""

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        super().__init__(f"{code}: {message}")


def externalize_assets(
    svg_text: str, assets_dir_name: str = "assets"
) -> tuple[str, tuple[RenderAsset, ...], Mapping[str, bytes]]:
    """Replace image data URIs and return SVG, contracts, and relative-path payloads."""
    _require_safe_relative_directory(assets_dir_name)
    if len(svg_text) > _MAX_SVG_CHARACTERS:
        raise AssetExternalizationError("svg_too_large", "SVG exceeds character limit")
    root = _parse_xml(svg_text)
    assets_by_hash: dict[str, RenderAsset] = {}
    payloads: dict[str, bytes] = {}
    total_bytes = 0
    for element in root.iter():
        if _local_name(element) != "image":
            continue
        for attribute_name, value in tuple(element.attrib.items()):
            if etree.QName(attribute_name).localname != "href" or not value.startswith("data:"):
                continue
            match = _DATA_URI.fullmatch(value)
            if match is None:
                raise AssetExternalizationError("asset_payload_invalid", "malformed data URI")
            media_type, encoded = match.groups()
            extension = _ALLOWED_MEDIA_TYPES.get(media_type.lower())
            if extension is None:
                raise AssetExternalizationError(
                    "asset_media_type_unsupported", f"unsupported data URI media type: {media_type}"
                )
            try:
                payload = base64.b64decode(encoded, validate=True)
            except (binascii.Error, ValueError) as error:
                raise AssetExternalizationError(
                    "asset_payload_invalid", "data URI contains invalid base64"
                ) from error
            if not payload or len(payload) > _MAX_ASSET_BYTES:
                raise AssetExternalizationError(
                    "asset_size_invalid", "decoded asset is empty or exceeds the size limit"
                )
            digest = hashlib.sha256(payload).hexdigest()
            existing = assets_by_hash.get(digest)
            if existing is None:
                if len(assets_by_hash) >= _MAX_ASSETS:
                    raise AssetExternalizationError("too_many_assets", "SVG asset count exceeds limit")
                total_bytes += len(payload)
                if total_bytes > _MAX_TOTAL_ASSET_BYTES:
                    raise AssetExternalizationError(
                        "asset_total_too_large", "decoded SVG assets exceed aggregate limit"
                    )
                relative_path = f"{assets_dir_name}/asset_{digest}.{extension}"
                existing = RenderAsset(
                    relative_path=relative_path,
                    media_type=media_type.lower(),
                    content_sha256=digest,
                    byte_size=len(payload),
                )
                assets_by_hash[digest] = existing
                payloads[relative_path] = payload
            element.set(attribute_name, existing.relative_path)
    rewritten = etree.tostring(root, encoding="unicode")
    if "data:image" in rewritten:
        raise AssetExternalizationError(
            "asset_externalization_incomplete", "rewritten SVG still contains image data"
        )
    return rewritten, tuple(assets_by_hash.values()), payloads


def write_assets(
    assets: tuple[RenderAsset, ...], payloads: Mapping[str, bytes], output_dir: Path
) -> None:
    """Write verified asset payloads below output_dir without permitting traversal."""
    root = output_dir.resolve()
    root.mkdir(parents=True, exist_ok=True)
    for asset in assets:
        payload = payloads.get(asset.relative_path)
        if payload is None:
            raise AssetExternalizationError(
                "asset_payload_missing", f"no bytes supplied for {asset.relative_path}"
            )
        digest = hashlib.sha256(payload).hexdigest()
        if digest != asset.content_sha256 or len(payload) != asset.byte_size:
            raise AssetExternalizationError(
                "asset_payload_mismatch", f"bytes do not match contract for {asset.relative_path}"
            )
        destination = (root / Path(asset.relative_path)).resolve()
        if not destination.is_relative_to(root):
            raise AssetExternalizationError(
                "asset_path_escape", f"asset path escapes output directory: {asset.relative_path}"
            )
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(payload)


def extract_fonts(pptx_path: Path, output_dir: Path) -> tuple[EmbeddedFont, ...]:
    """Extract opaque embedded font parts and report unsatisfied theme font families."""
    try:
        with ZipFile(pptx_path) as archive:
            infos = archive.infolist()
            if len(infos) > _MAX_ZIP_PARTS:
                raise FontExtractionError("pptx_too_many_parts", "PPTX part count exceeds limit")
            font_infos = tuple(info for info in infos if _is_font_part(info))
            if len(font_infos) > _MAX_FONT_PARTS:
                raise FontExtractionError("too_many_font_parts", "embedded font count exceeds limit")
            if any(info.file_size > _MAX_FONT_BYTES for info in font_infos):
                raise FontExtractionError("font_part_too_large", "embedded font part exceeds limit")
            embedded = _embedded_font_bindings(archive, font_infos)
            theme_families = _theme_font_families(archive, infos)
            output_dir.mkdir(parents=True, exist_ok=True)
            results: list[EmbeddedFont] = []
            embedded_families: set[str] = set()
            used_paths: set[str] = set()
            for family, info in embedded:
                relative_path = _font_relative_path(family, info, used_paths)
                payload = _bounded_read(archive, info)
                destination = output_dir / Path(relative_path)
                destination.parent.mkdir(parents=True, exist_ok=True)
                destination.write_bytes(payload)
                results.append(
                    EmbeddedFont(family=family, relative_path=relative_path, embedded=True)
                )
                embedded_families.add(family.casefold())
            for family in sorted(theme_families, key=str.casefold):
                if family.casefold() not in embedded_families:
                    results.append(EmbeddedFont(family=family, embedded=False))
            return tuple(results)
    except FontExtractionError:
        raise
    except (BadZipFile, OSError, KeyError, etree.XMLSyntaxError) as error:
        raise FontExtractionError("pptx_archive_invalid", f"cannot inspect PPTX fonts: {error}") from error


def _parse_xml(svg_text: str) -> etree._Element:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False, huge_tree=False)
    try:
        return etree.fromstring(svg_text.encode("utf-8"), parser)
    except (etree.XMLSyntaxError, ValueError) as error:
        raise AssetExternalizationError("invalid_svg", f"SVG is not well-formed: {error}") from error


def _local_name(element: etree._Element) -> str:
    return etree.QName(element.tag).localname if isinstance(element.tag, str) else ""


def _require_safe_relative_directory(value: str) -> None:
    path = PurePosixPath(value)
    if not value or path.is_absolute() or any(part in {"", ".", ".."} for part in path.parts):
        raise AssetExternalizationError("asset_directory_invalid", "asset directory must be relative")
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._/-]{0,120}", value):
        raise AssetExternalizationError("asset_directory_invalid", "asset directory is not portable")


def _is_font_part(info: ZipInfo) -> bool:
    return info.filename.startswith("ppt/fonts/") and info.filename.endswith(".fntdata")


def _bounded_read(archive: ZipFile, part: str | ZipInfo) -> bytes:
    info = archive.getinfo(part) if isinstance(part, str) else part
    if info.file_size > _MAX_XML_BYTES and not _is_font_part(info):
        raise FontExtractionError("pptx_xml_too_large", f"XML part exceeds limit: {info.filename}")
    if info.file_size > _MAX_FONT_BYTES and _is_font_part(info):
        raise FontExtractionError("font_part_too_large", "embedded font part exceeds limit")
    return archive.read(info)


def _xml_root(archive: ZipFile, name: str) -> etree._Element:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False, huge_tree=False)
    return etree.fromstring(_bounded_read(archive, name), parser)


def _embedded_font_bindings(
    archive: ZipFile, font_infos: tuple[ZipInfo, ...]
) -> tuple[tuple[str, ZipInfo], ...]:
    names = {info.filename: info for info in font_infos}
    if "ppt/presentation.xml" not in archive.namelist():
        return ()
    presentation = _xml_root(archive, "ppt/presentation.xml")
    relationships = _xml_root(archive, "ppt/_rels/presentation.xml.rels")
    targets = {
        node.get("Id", ""): f"ppt/{node.get('Target', '')}"
        for node in relationships.findall(f"{{{_REL_NS}}}Relationship")
    }
    bindings: list[tuple[str, ZipInfo]] = []
    for embedded in presentation.findall(f".//{{{_P_NS}}}embeddedFont"):
        font = embedded.find(f"{{{_P_NS}}}font")
        family = font.get("typeface", "").strip() if font is not None else ""
        if not family or len(family) > 128:
            continue
        for variant in embedded:
            relationship_id = variant.get(f"{{{_R_NS}}}id")
            target = targets.get(relationship_id or "")
            if target in names:
                bindings.append((family, names[target]))
    return tuple(bindings)


def _theme_font_families(archive: ZipFile, infos: list[ZipInfo]) -> set[str]:
    families: set[str] = set()
    for info in infos:
        if not info.filename.startswith("ppt/theme/") or not info.filename.endswith(".xml"):
            continue
        root = _xml_root(archive, info.filename)
        for node in root.findall(f".//{{{_A_NS}}}fontScheme//*[@typeface]"):
            family = node.get("typeface", "").strip()
            if family and not family.startswith("+") and len(family) <= 128:
                families.add(family)
    return families


def _font_relative_path(family: str, info: ZipInfo, used: set[str]) -> str:
    safe_family = re.sub(r"[^A-Za-z0-9._-]+", "_", family).strip("._-") or "font"
    candidate = f"fonts/{safe_family}.fntdata"
    if candidate in used:
        candidate = f"fonts/{safe_family}_{Path(info.filename).stem}.fntdata"
    used.add(candidate)
    return candidate

